        {/* 跨域复用远程子应用的业务卡片 */}
        <div className="mt-6">
          <Suspense fallback={<div className="h-20 bg-slate-800 animate-pulse rounded" />}>
            <RemoteOrderCard orderId="ORD-2026-9981" />
          </Suspense>
        </div>
      </aside>

      <main className="flex-1 p-8">
